import json, re, hashlib, math, sys, csv
from pathlib import Path
from fractions import Fraction
from decimal import Decimal, ROUND_HALF_EVEN, ROUND_HALF_UP

ART = Path('/home/simon/dev/thesis/results/seed43-overview-20261115-evening')
TARGETS = ['t1n', 't1c', 't2w', 't2f']
CASE_RE = re.compile(r'^(BraTS-GLI-\d{5}-\d{3}): PSNR=([^,]+), SSIM=([^,]+), MSE=(\S+)\s*$')

def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()

def parse_text(p):
    rows = []
    for line in Path(p).read_text().splitlines():
        m = CASE_RE.match(line.strip())
        if m:
            rows.append((m.group(1), float(m.group(2)), float(m.group(3))))
    return rows

def header_values(p):
    t = Path(p).read_text()
    ps = re.search(r'PSNR:\s+([-\d.]+)', t); ss = re.search(r'SSIM:\s+([-\d.]+)', t)
    n = re.search(r'Number of samples:\s+(\d+)', t)
    return float(ps.group(1)), float(ss.group(1)), int(n.group(1))

inv = json.load(open(ART / 'verification.json'))['results']
out = []
problems = []
all_case_sets = set()
for i, r in enumerate(inv):
    d = Path(r['metric_directory'])
    key = (r['source'], float(r['sigma']), int(r['batch']), int(r['updates']))
    rec = dict(idx=i, key=key, dir=str(d))
    if 'valfull' not in d.name or 'val50' in str(d):
        problems.append((key, 'not valfull dir', d.name))
    mj = d / 'metrics.json'
    per = {}
    case_sets = {}
    if mj.exists() and r['precision'] == 'full_precision_json':
        data = json.loads(mj.read_text(), parse_constant=lambda c: float('nan'))
        extra = set(data) - set(TARGETS)
        if extra or set(data) != set(TARGETS):
            problems.append((key, 'json target keys', sorted(data)))
        for t in TARGETS:
            rows = data[t]
            ids = [x['subject'] for x in rows]
            ps = [x['masked']['psnr'] for x in rows]; ss = [x['masked']['ssim'] for x in rows]
            if not all(isinstance(v, (int, float)) and math.isfinite(v) for v in ps + ss):
                problems.append((key, t, 'non-finite'))
            if len(ids) != 219 or len(set(ids)) != 219:
                problems.append((key, t, 'count', len(ids), len(set(ids))))
            case_sets[t] = frozenset(ids)
            per[t] = (math.fsum(ps) / len(ps), math.fsum(ss) / len(ss))
            # cross-check masked text file: rounded per-case values agree with JSON masked (and not full)
            tx = parse_text(d / f'metrics-{t}.txt')
            txd = {a: (b, c) for a, b, c in tx}
            bad = 0
            for x in rows:
                b, c = txd[x['subject']]
                if abs(b - x['masked']['psnr']) > 0.005 + 1e-9 or abs(c - x['masked']['ssim']) > 0.00005 + 1e-9:
                    bad += 1
            if bad or len(tx) != 219:
                problems.append((key, t, 'text/json masked mismatch', bad, len(tx)))
            hp, hs, hn = header_values(d / f'metrics-{t}.txt')
            if hn != 219 or abs(hp - per[t][0]) > 0.005 + 1e-9 or abs(hs - per[t][1]) > 0.00005 + 1e-9:
                problems.append((key, t, 'header mismatch', hp, hs, hn, per[t]))
        rec['hash_ok'] = (sha(mj) == r['sha256'].get('metrics.json'))
        rec['sha'] = {'metrics.json': sha(mj)}
        rec['kind'] = 'json'
    else:
        rec['kind'] = 'text'
        rec['sha'] = {}
        hok = True
        for t in TARGETS:
            p = d / f'metrics-{t}.txt'
            rows = parse_text(p)
            ids = [a for a, _, _ in rows]
            if len(ids) != 219 or len(set(ids)) != 219:
                problems.append((key, t, 'count', len(ids), len(set(ids))))
            if not all(math.isfinite(b) and math.isfinite(c) for _, b, c in rows):
                problems.append((key, t, 'non-finite'))
            case_sets[t] = frozenset(ids)
            per[t] = (math.fsum(b for _, b, _ in rows) / len(rows), math.fsum(c for _, _, c in rows) / len(rows))
            hp, hs, hn = header_values(p)
            if hn != 219 or abs(hp - per[t][0]) > 0.006 or abs(hs - per[t][1]) > 0.0001:
                problems.append((key, t, 'header mismatch', hp, hs, hn, per[t]))
            # masked file must differ from full file
            fp, fs, _ = header_values(d / f'metrics-full-{t}.txt')
            if abs(fs - hs) < 0.05:
                problems.append((key, t, 'masked ~ full?', hs, fs))
            h = sha(p); rec['sha'][f'metrics-{t}.txt'] = h
            hok &= (h == r['sha256'].get(f'metrics-{t}.txt'))
        rec['hash_ok'] = hok
    if len(set(case_sets.values())) != 1:
        problems.append((key, 'case sets differ across targets'))
    all_case_sets |= set(case_sets.values())
    rec['per'] = per
    rec['psnr'] = sum(per[t][0] for t in TARGETS) / 4
    rec['ssim'] = sum(per[t][1] for t in TARGETS) / 4
    rec['inv_psnr'] = r['psnr']; rec['inv_ssim'] = r['ssim']; rec['precision'] = r['precision']
    out.append(rec)

print('records', len(out), 'json', sum(r['kind']=='json' for r in out), 'text', sum(r['kind']=='text' for r in out))
print('unique keys', len({r['key'] for r in out}))
print('distinct case-id sets across all records/targets', len(all_case_sets), [len(s) for s in all_case_sets])
print('hash ok', sum(r['hash_ok'] for r in out))
print('problems', len(problems))
for p in problems: print('  ', p)

# compare to inventory and CSV
rows = list(csv.DictReader(open(ART / 'scores.csv')))
print('csv rows', len(rows))
csvd = {}
for c in rows:
    k = (c['source'], float(c['sigma']), int(c['batch']), int(c['updates']))
    if k in csvd: print('dup csv key', k)
    csvd[k] = c
    if c['seed'] != '43': print('seed!', c)
maxd = 0
for r in out:
    c = csvd.get(r['key'])
    if c is None: print('missing in csv', r['key']); continue
    ds = abs(float(c['ssim']) - r['ssim']); dp = abs(float(c['psnr']) - r['psnr'])
    di = max(abs(r['inv_ssim'] - r['ssim']), abs(r['inv_psnr'] - r['psnr']))
    maxd = max(maxd, ds, dp, di)
    if ds > 1e-12 or dp > 1e-11 or di > 1e-11:
        print('value diff', r['key'], ds, dp, di)
print('csv keys not in recompute', set(csvd) - {r['key'] for r in out})
print('max abs diff vs csv/inventory', maxd)

def rnd(x, n):
    return str(Decimal(repr(x)).quantize(Decimal(1).scaleb(-n), rounding=ROUND_HALF_EVEN))
# borderline check
for r in out:
    for name, n in (('ssim', 4), ('psnr', 2)):
        v = r[name]; scaled = v * 10**n
        frac = scaled - math.floor(scaled)
        if abs(frac - 0.5) < (0.02 if r['kind']=='text' else 1e-6):
            print('near rounding boundary', r['key'], name, v, r['kind'])
json.dump([dict(key=list(r['key']), ssim=r['ssim'], psnr=r['psnr'], ssim4=rnd(r['ssim'],4), psnr2=rnd(r['psnr'],2),
                kind=r['kind'], dir=r['dir'], sha=r['sha'], hash_ok=r['hash_ok'],
                per={t: list(v) for t, v in r['per'].items()}) for r in out],
          open('/tmp/audit_seed43/recomputed.json', 'w'), indent=1)
