    bs = sorted([t for t in T if t['s'] in ('BS1', 'BS4')], key=lambda t: t['cx'])
    up = sorted([t for t in T if t['s'].endswith('updates')], key=lambda t: t['cx'])
    assert len(bs) == 15 and len(up) == 15
    colx = [t['cx'] for t in bs]
    for i, (sig, b, u) in enumerate(COLS):
        if bs[i]['s'] != f'BS{b}' or up[i]['s'] != f'{u/1000:g}k updates' or abs(up[i]['cx'] - colx[i]) > 0.05:
            issues.append((metric, 'tick label', i, bs[i]['s'], up[i]['s']))
    sig_lbl = sorted([t for t in T if t['s'].startswith('σ')], key=lambda t: t['cx'])
    for g, t in enumerate(sig_lbl):
        exp = f'σ = {[0, 0.5, 1, 1.5, 2][g]:g}'
        if t['s'] != exp or abs(t['cx'] - colx[3*g+1]) > 0.05: issues.append((metric, 'sigma label', t['s'], t['cx'], colx[3*g+1]))
    rows = {t['s']: t for t in T if t['s'] in LABELS}
    rowy = [rows[l]['y'] for l in LABELS]  # baseline of right-aligned labels; same va=center convention
    pitch = [round(colx[i+1]-colx[i], 3) for i in range(14)]
    vals = [t for t in T if re.fullmatch(r'\d+\.\d+', t['s'])]
    assert len(vals) == 89, len(vals)
    seen = {}
    for t in vals:
        ci = min(range(15), key=lambda i: abs(colx[i] - t['cx'])); ri = min(range(6), key=lambda i: abs(rowy[i] - t['y']))
        dx = t['cx'] - colx[ci]; dy = t['y'] - rowy[ri]
        if abs(dx) > 1.0 or abs(dy) > 3.0: issues.append((metric, 'offset', t['s'], dx, dy))
        key = (SOURCES[ri], *COLS[ci])
        if key in seen: issues.append((metric, 'duplicate cell', key))
        seen[key] = t
    running = [t for t in T if t['s'] == 'Running']
    assert len(running) == 1
    rci = min(range(15), key=lambda i: abs(colx[i] - running[0]['cx'])); rri = min(range(6), key=lambda i: abs(rowy[i] - running[0]['y']))
    run_key = (SOURCES[rri], *COLS[rci])
    if run_key != ('mlp8_random', 2.0, 1, 10000): issues.append((metric, 'running at', run_key))
    if set(seen) != set(rec): issues.append((metric, 'cell set mismatch', set(seen) ^ set(rec)))
    # value + bold + outline check
    rects = [r for r in E['rects'] if r['axes'] == axes]
    rect_cells = set()
    for r in rects:
        ci = min(range(15), key=lambda i: abs(colx[i] - r['cx'])); ri = min(range(6), key=lambda i: abs(rowy[i] - (r['cy'])))
        rect_cells.add((SOURCES[ri], *COLS[ci]))
        if abs(r['cx'] - colx[ci]) > 0.6: issues.append((metric, 'rect x offset', r))
    mism = 0
    best_cells = set()
    for ci, col in enumerate(COLS):
        present = [(s, *col) for s in SOURCES if (s, *col) in rec]
        disp = {k: fmt(rec[k][metric], n) for k in present}
        top = max(Decimal(v) for v in disp.values())
        best = {k for k, v in disp.items() if Decimal(v) == top}
        best_cells |= best
        for k in present:
            t = seen[k]
            if t['s'] != disp[k]: mism += 1; issues.append((metric, 'VALUE', k, t['s'], disp[k]))
            if (t['weight'] == 'bold') != (k in best): issues.append((metric, 'BOLD', k, t['weight']))
    if rect_cells != best_cells: issues.append((metric, 'RECT', rect_cells ^ best_cells))
    summary[metric] = dict(values=len(vals), mismatches=mism, bold=sum(t['weight'] == 'bold' for t in vals), rects=len(rects),
                           running=run_key, pitch=sorted(set(pitch)), rows=[round(y, 2) for y in rowy])
    # report best per column
    print(metric, 'best per column:')
    for ci, col in enumerate(COLS):
        b = [(k[0], fmt(rec[k][metric], n)) for k in best_cells if k[1:] == col]
        print('   ', col, b, '(incomplete col)' if col == (2.0, 1, 10000) else '')
print(json.dumps(summary, indent=0))
print('ISSUES', len(issues))
for i in issues: print('  ', i)
